// 从 project-v2-interface 导入基础接口
import {
    getActionUtils,
    getTriggerUtils,
    ITriggerAction,
    triggerGroupUtils,
    actionGroupUtils
} from '@droid/project-v2-interface'
// 从 project-v2-ext 导入具体实现类型
import {
    actionNodeActionType,
    IActionNodeActionData,
    IActionNodeActionJavaData,
    ITriggerNodeTriggerData,
    ITriggerNodeTriggerJavaData,
    triggerNodeTriggerType,
    SelectorOperation,
    ActionType
} from '@droid/project-v2-ext'
import { Log } from '@fanfanlo'
import { ulid } from 'ulid'
const fileLog = new Log(false, 'nodeClickUtils_f')
fileLog.pause = false
fileLog.childrenPaused = false

/**
 * 创建 NodeTrigger + NodeAction 的 TriggerAction 对
 *
 * @param pn - 包名
 * @param an - Activity名
 * @param cn - 类名(可选)
 * @param node - 节点数据
 * @returns ITriggerAction
 */
export function createNodeTriggerActionPair(
    pn: string,
    an: string,
    cn: string | null,
    node: any
): ITriggerAction {
    fileLog.log('[createNodeTriggerActionPair] called, pn:', pn, 'an:', an, 'cn:', cn, 'node:', node)

    // 获取 trigger utils
    const triggerUtils = getTriggerUtils(triggerNodeTriggerType)
    fileLog.log('[createNodeTriggerActionPair] triggerUtils for type:', triggerNodeTriggerType, 'found:', !!triggerUtils)
    if (!triggerUtils) {
        throw new Error(`[createNodeTriggerActionPair] triggerUtils not found for type: ${triggerNodeTriggerType}`)
    }

    // 使用 mergeDataToDefaultData 创建 trigger 数据
    const triggerUlid = ulid()
    const operations = nodeToSelectorChain(node)
    fileLog.log('[createNodeTriggerActionPair] triggerUlid:', triggerUlid, 'selectorChain operations count:', operations.length)

    const triggerJavaData: ITriggerNodeTriggerJavaData = {
        pn,
        an,
        cn: cn || undefined,
        selectorChain: {
            operations: operations
        }
    }
    const triggerData = triggerUtils.mergeDataToDefaultData({
        ulid: triggerUlid,
        javaData: triggerJavaData
    }) as ITriggerNodeTriggerData
    fileLog.log('[createNodeTriggerActionPair] triggerData created, permissions:', triggerData.permissions?.length || 0, 'injects:', triggerData.injects?.length || 0, 'data:', triggerData)

    // 获取 action utils
    const actionUtils = getActionUtils(actionNodeActionType)
    fileLog.log('[createNodeTriggerActionPair] actionUtils for type:', actionNodeActionType, 'found:', !!actionUtils)
    if (!actionUtils) {
        throw new Error(`[createNodeTriggerActionPair] actionUtils not found for type: ${actionNodeActionType}`)
    }

    // 使用 mergeDataToDefaultData 创建 action 数据
    const actionUlid = ulid()

    const actionJavaData: IActionNodeActionJavaData = {
        actionType: ActionType.click,
        clickConfig: {
            useGlobalClick: false
        }
    }
    const actionData = actionUtils.mergeDataToDefaultData({
        ulid: actionUlid,
        javaData: actionJavaData
    }) as IActionNodeActionData
    fileLog.log('[createNodeTriggerActionPair] actionData created, actionUlid:', actionUlid, 'permissions:', actionData.permissions?.length || 0, 'injects:', actionData.injects?.length || 0, 'data:', actionData)

    // 创建 actionGroup (IGroup<IActionData>)
    const actionGroup = actionGroupUtils.mergeDataToDefaultData({
        list: [actionData.ulid],
        children: [actionData],
        checks: [[true]],
        isSequential: true
    })
    fileLog.log('[createNodeTriggerActionPair] actionGroup created, ulid:', actionGroup.ulid, 'list:', JSON.stringify(actionGroup.list))

    // 创建 triggerGroup (IGroup<ITriggerData>)
    const triggerGroup = triggerGroupUtils.mergeDataToDefaultData({
        list: [triggerData.ulid],
        children: [triggerData],
        checks: [[true]],
        isSequential: true
    })
    fileLog.log('[createNodeTriggerActionPair] triggerGroup created, ulid:', triggerGroup.ulid, 'list:', JSON.stringify(triggerGroup.list))

    // 创建 triggerAction
    const triggerActionUlid = ulid()
    const triggerAction: ITriggerAction = {
        
        ulid: triggerActionUlid,
        uuid: '',
        triggerGroupUuid: triggerGroup.uuid,
        triggerGroupUlid: triggerGroup.ulid,
        actionGroupUuid: actionGroup.uuid,
        actionGroupUlid: actionGroup.ulid,
        triggerGroup,
        actionGroup,
        createdAt: Date.now(),
        updatedAt: Date.now()
    } as ITriggerAction
    fileLog.log('[createNodeTriggerActionPair] triggerAction created, ulid:', triggerAction.ulid, 'triggerGroupUlid:', triggerAction.triggerGroupUlid, 'actionGroupUlid:', triggerAction.actionGroupUlid)

    return triggerAction
}

/**
 * Node 布尔属性名称枚举
 * 定义 A11y Node 对象的布尔属性名称
 */
enum NodeBooleanProperty {
    IS_CLICKABLE = 'isClickable',
    IS_ENABLED = 'isEnabled',
    IS_VISIBLE_TO_USER = 'isVisibleToUser',
    IS_SCROLLABLE = 'isScrollable',
    IS_CHECKABLE = 'isCheckable',
    IS_CHECKED = 'isChecked',
    IS_FOCUSABLE = 'isFocusable',
    IS_SELECTED = 'isSelected'
}

/**
 * ISelectorOperation 接口定义
 */
interface ISelectorOperation {
    method: SelectorOperation
    value: any
}

/**
 * 将 A11y Node 数据转换为 SelectorChain operations
 *
 * @param node - A11y 节点数据
 * @returns operations 数组
 */
function nodeToSelectorChain(node: any): ISelectorOperation[] {
    const operations: ISelectorOperation[] = []

    fileLog.log('[nodeToSelectorChain] 开始转换, node:', JSON.stringify(node))

    // 1. text - 优先级最高,如果有文本就使用
    if (node.text && typeof node.text === 'string' && node.text.trim() !== '') {
        const textValue = node.text.trim()
        fileLog.log('[nodeToSelectorChain] 添加 text selector:', textValue)
        operations.push({
            method: SelectorOperation.TEXT,
            value: textValue
        })
    }

    // 2. className - 几乎所有节点都有,作为辅助条件
    if (node.className && typeof node.className === 'string') {
        fileLog.log('[nodeToSelectorChain] 添加 className selector:', node.className)
        operations.push({
            method: SelectorOperation.CLASS_NAME,
            value: node.className
        })
    }

    // 3. 如果没有 text,考虑使用其他属性
    if (!node.text || node.text.trim() === '') {
        fileLog.log('[nodeToSelectorChain] 节点没有 text,考虑添加其他属性')

        // contentDescription (desc)
        if (node.contentDescription && typeof node.contentDescription === 'string' && node.contentDescription.trim() !== '') {
            fileLog.log('[nodeToSelectorChain] 添加 desc selector:', node.contentDescription)
            operations.push({
                method: SelectorOperation.DESC,
                value: node.contentDescription.trim()
            })
        }

        // resourceId (id)
        if (node.viewIdResourceName && typeof node.viewIdResourceName === 'string' && node.viewIdResourceName.trim() !== '') {
            fileLog.log('[nodeToSelectorChain] 添加 id selector:', node.viewIdResourceName)
            operations.push({
                method: SelectorOperation.ID,
                value: node.viewIdResourceName.trim()
            })
        }
    }

    // 4. 布尔属性 - 作为辅助条件(仅在有明确值时添加)
    const booleanAttrs: { key: NodeBooleanProperty; method: SelectorOperation }[] = [
        { key: NodeBooleanProperty.IS_CLICKABLE, method: SelectorOperation.CLICKABLE },
        { key: NodeBooleanProperty.IS_ENABLED, method: SelectorOperation.ENABLED },
        { key: NodeBooleanProperty.IS_VISIBLE_TO_USER, method: SelectorOperation.VISIBLE_TO_USER },
        { key: NodeBooleanProperty.IS_SCROLLABLE, method: SelectorOperation.SCROLLABLE },
        { key: NodeBooleanProperty.IS_CHECKABLE, method: SelectorOperation.CHECKABLE },
        { key: NodeBooleanProperty.IS_CHECKED, method: SelectorOperation.CHECKED },
        { key: NodeBooleanProperty.IS_FOCUSABLE, method: SelectorOperation.FOCUSABLE },
        { key: NodeBooleanProperty.IS_SELECTED, method: SelectorOperation.SELECTED }
    ]

    for (const attr of booleanAttrs) {
        if (typeof node[attr.key] === 'boolean') {
            // 只添加有区分性的属性(true 的情况,或者对定位很重要的属性)
            if (node[attr.key] === true && (attr.key === NodeBooleanProperty.IS_CLICKABLE || attr.key === NodeBooleanProperty.IS_ENABLED)) {
                fileLog.log('[nodeToSelectorChain] 添加', attr.method, 'selector:', node[attr.key])
                operations.push({
                    method: attr.method,
                    value: node[attr.key]
                })
            }
        }
    }

    // 5. bounds - 作为最后的兜底方案(当其他属性都不够唯一时)
    // 注意: bounds 可能随屏幕尺寸变化,所以优先级最低
    if (operations.length === 0 && node.boundsInScreen) {
        const bounds = node.boundsInScreen
        if (
            typeof bounds.left === 'number' &&
            typeof bounds.top === 'number' &&
            typeof bounds.right === 'number' &&
            typeof bounds.bottom === 'number'
        ) {
            fileLog.log('[nodeToSelectorChain] 其他属性不足,添加 bounds selector:', bounds)
            operations.push({
                method: SelectorOperation.BOUNDS,
                value: {
                    left: bounds.left,
                    top: bounds.top,
                    right: bounds.right,
                    bottom: bounds.bottom
                }
            })
        }
    }

    fileLog.log('[nodeToSelectorChain] 转换完成, count:', operations.length, 'operations:', JSON.stringify(operations))

    return operations
}
