import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";
import type { IProjectProject, ITriggerActionGroupInput, IUpdateTriggerActionGroupInput } from "./types";

/**
 * Upsert Project 的输入类型
 * 基于 IProjectProject，排除后端生成的字段
 * uuid 为空字符串或不传表示创建，有值表示更新
 */
export type IUpsertProjectData =
    Partial<Omit<IProjectProject, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children' | 'triggerActionGroup'>>
    & {
        type: string;
        category: string;
        visibility: string;
        children?: ITriggerActionGroupInput[] | IUpdateTriggerActionGroupInput[];
    };

/**
 * Upsert Project 的请求参数
 */
export interface IUpsertProjectParams extends IRequestParams {
    data: IUpsertProjectData;
}

/**
 * Upsert Project 的返回结果
 */
export interface IUpsertProjectResultBody extends IResultContent {
    is_ok: boolean;
    msg: string;
    project?: IProjectProject;
    isCreated?: boolean;
    changes?: Record<string, unknown>;
    deletedChildren?: string[];
    createdChildren?: string[];
    oldVisibility?: string;
}

/**
 * 创建或更新项目（合并接口）
 * uuid 为空字符串或不传表示创建，有值表示更新
 * @param opts 请求选项
 * @returns 操作结果
 */
export async function upsertProject(opts: IRequestOptions<IUpsertProjectParams>) {
    const isCreate = !opts.params.data.uuid;
    const operationType = isCreate ? '创建' : '更新';
    console.log('[upsertProject] 开始' + operationType + '项目, params:', JSON.stringify(opts.params));

    const res = await request<IUpsertProjectResultBody>(
        tms.TProject,
        tms.MProjectUpsertProject,
        opts.params,
        opts.gateway,
        opts.handler
    );

    if (res.shellIsOk) {
        console.log('[upsertProject] 请求成功, shellIsOk:', res.shellIsOk);
    } else {
        console.log('[upsertProject] 请求失败, shellIsOk:', res.shellIsOk, 'err:', res.err);
    }

    if (res.dataIsOk) {
        console.log('[upsertProject] 数据正常, dataIsOk:', res.dataIsOk);
    } else {
        console.log('[upsertProject] 数据异常, dataIsOk:', res.dataIsOk, 'errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.is_ok) {
            const resultType = res.data.isCreated ? '创建' : '更新';
            console.log('[upsertProject] ' + resultType + '成功, project.uuid:', res.data.project?.uuid);
            if (res.data.changes) {
                console.log('[upsertProject] 变更信息:', JSON.stringify(res.data.changes));
            }
            if (res.data.deletedChildren) {
                console.log('[upsertProject] 删除的子级:', JSON.stringify(res.data.deletedChildren));
            }
            if (res.data.createdChildren) {
                console.log('[upsertProject] 创建的子级:', JSON.stringify(res.data.createdChildren));
            }
        } else {
            console.log('[upsertProject] ' + operationType + '失败, msg:', res.data.msg);
        }
    } else {
        console.log('[upsertProject] 无返回数据');
    }

    return res;
}

export default upsertProject;
