import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { Log } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";

const fileLog = new Log(false, 'getProjectR2Url_f');
// fileLog.pause = true;

/**
 * 获取项目R2 URL的请求参数
 */
export interface IGetProjectR2UrlParams extends IRequestParams {
    data: {
        uuid: string;  // 必填：项目UUID
    };
}

/**
 * 获取项目R2 URL的返回结果
 */
export interface IGetProjectR2UrlResult extends IResultContent {
    is_ok: boolean;
    msg?: string;
    url?: string;  // R2完整URL: https://{CDNDomain}/{cfId}/project/{ULID}/project.json
}

/**
 * 获取项目在R2的project.json完整URL
 * 仅支持public且未删除的项目
 * @param opts 请求选项
 * @returns R2 URL
 */
export async function getProjectR2Url(opts: IRequestOptions<IGetProjectR2UrlParams>) {
    const fnLog = fileLog.sub(false, 'getProjectR2Url_fn');
    // fnLog.pause = true;

    fnLog.log('[getProjectR2Url] 开始获取项目R2 URL, params:', JSON.stringify(opts.params));

    const res = await request<IGetProjectR2UrlResult>(
        tms.TProject,
        tms.MProjectGetProjectR2Url,
        opts.params,
        opts.gateway,
        opts.handler
    );

    fnLog.log('[getProjectR2Url] 请求完成, shellIsOk:', res.shellIsOk, 'dataIsOk:', res.dataIsOk);

    if (!res.shellIsOk) {
        fnLog.log('[getProjectR2Url] ERROR: 请求失败, err:', JSON.stringify(res.err));
    }

    if (!res.dataIsOk) {
        fnLog.log('[getProjectR2Url] ERROR: 数据异常, errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.is_ok) {
            fnLog.log('[getProjectR2Url] 获取成功, url:', res.data.url);
        } else {
            fnLog.log('[getProjectR2Url] ERROR: 获取失败, msg:', res.data.msg);
        }
    } else {
        fnLog.log('[getProjectR2Url] ERROR: 无返回数据');
    }

    return res;
}

export default getProjectR2Url;
